def is_valid(s: str) -> bool:
    # Define matching pairs for brackets
    matching = {')': '(', ']': '[', '}': '{'}

    # Initialize two stacks:
    # open_stack to store opening brackets and wildcards
    # star_stack to store positions of wildcards
    open_stack = []
    star_stack = []

    # Iterate through each character in the string
    for i, char in enumerate(s):
        if char in matching.values():
            # Push opening brackets and wildcards onto the open_stack
            open_stack.append((char, i))
        elif char in matching.keys():
            # If the stack is empty or the top of the stack doesn't match the current closing bracket, return False
            if not open_stack:
                return False
            top_char, top_index = open_stack.pop()
            if top_char != matching[char]:
                # Try to use a wildcard to match the current closing bracket
                if star_stack:
                    # Find the rightmost wildcard that can match the current closing bracket
                    j = len(star_stack) - 1
                    while j >= 0 and (s[star_stack[j]] != '(' and s[star_stack[j]] != '[' and s[star_stack[j]] != '{'):
                        j -= 1
                    if j >= 0:
                        star_stack.pop(j)
                    else:
                        return False
                else:
                    return False
        else:
            # Push the position of the wildcard '*' onto the star_stack
            star_stack.append(i)

    # After processing all characters, ensure the stack is empty
    while open_stack:
        # If the stack is empty, return False
        if not star_stack:
            return False

        # Try to use a wildcard to match the remaining opening bracket
        top_char, top_index = open_stack.pop()
        if top_char == '(':
            # Find the leftmost wildcard that can match the current opening bracket
            j = 0
            while j < len(star_stack) and (s[star_stack[j]] != ')' and s[star_stack[j]] != ']' and s[star_stack[j]] != '}'):
                j += 1
            if j < len(star_stack):
                star_stack.pop(j)
            else:
                return False
        else:
            # Find the rightmost wildcard that can match the current opening bracket
            j = len(star_stack) - 1
            while j >= 0 and (s[star_stack[j]] != ')' and s[star_stack[j]] != ']' and s[star_stack[j]] != '}'):
                j -= 1
            if j >= 0:
                star_stack.pop(j)
            else:
                return False

    return len(open_stack) == 0

# Example usage:
print(is_valid("(*)"))  # True
print(is_valid("(*))"))  # False
print(is_valid("((()))"))  # True
print(is_valid("([{}])"))  # True
print(is_valid("([)]"))  # False
