print(is_valid("(*[(*)]*(()))"))  # True
print(is_valid("(*[(*)]*(()))("))  # False
print(is_valid("(*[(*)]*(()))((*))"))  # True
print(is_valid("(*[(*)]*(()))((*))("))  # False
